import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Hướng dẫn Phiên bản và Bảo trì Tài liệu","description":"","frontmatter":{},"headers":[],"relativePath":"vi/99-文档版本与维护说明.md","filePath":"vi/99-文档版本与维护说明.md"}'),u={name:"vi/99-文档版本与维护说明.md"};function c(l,n,o,g,r,e){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="huong-dan-phien-ban-va-bao-tri-tai-lieu" tabindex="-1">Hướng dẫn Phiên bản và Bảo trì Tài liệu <a class="header-anchor" href="#huong-dan-phien-ban-va-bao-tri-tai-lieu" aria-label="Permalink to &quot;Hướng dẫn Phiên bản và Bảo trì Tài liệu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>99</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>quản lý phiên bản, hướng dẫn bảo trì, chuẩn mực tài liệu, nhật ký cập nhật, bảo trì cài đặt</td></tr></tbody></table><h2 id="_1-tong-quan-he-thong-tai-lieu" tabindex="-1">1. Tổng quan Hệ thống Tài liệu <a class="header-anchor" href="#_1-tong-quan-he-thong-tai-lieu" aria-label="Permalink to &quot;1. Tổng quan Hệ thống Tài liệu&quot;">​</a></h2><p>Hệ thống cài đặt Văn minh Cộng sinh Mỏ neo bao gồm 100 tài liệu Markdown, được đánh số từ 00 đến 99, chia thành mười mô-đun, mỗi mô-đun có 10 tài liệu. Hệ thống tài liệu áp dụng SPEC.md (Chuẩn mực Tạo tài liệu) làm ràng buộc nghiêm ngặt, 00-Tổng quan Vũ trụ Hengyuanzhou làm nguyên tắc tổng thể, tài liệu của mỗi mô-đun được mở rộng chi tiết từ các chiều khác nhau, và cuối cùng các tài liệu phụ lục 90-99 thực hiện lập chỉ mục, tổng hợp và tổ chức. Toàn bộ hệ thống tài liệu cấu thành một cơ sở kiến thức cài đặt hoàn chỉnh, tự nhất quán về mặt logic, phân cấp rõ ràng và tham chiếu lẫn nhau.</p><p>Thiết kế hệ thống tài liệu tuân theo ba nguyên tắc: &quot;đơn vị mô-đun, có cấu trúc, có thể mở rộng&quot;. Đơn vị mô-đun có nghĩa là mỗi tài liệu tập trung vào một chủ đề cụ thể và hoàn chỉnh độc lập; có cấu trúc có nghĩa là tất cả các tài liệu tuân theo chuẩn mực định dạng thống nhất, thuận tiện cho việc đọc và tra cứu; có thể mở rộng có nghĩa là hệ thống tài liệu dành đủ không gian mở rộng, có thể liên tục cải thiện cài đặt thông qua việc sửa đổi tài liệu hiện có và bổ sung nội dung mới.</p><h2 id="_2-quy-tac-đanh-so-phien-ban" tabindex="-1">2. Quy tắc Đánh số Phiên bản <a class="header-anchor" href="#_2-quy-tac-đanh-so-phien-ban" aria-label="Permalink to &quot;2. Quy tắc Đánh số Phiên bản&quot;">​</a></h2><p>Hệ thống tài liệu áp dụng quy tắc đánh số phiên bản ba cấp: &quot;số phiên bản chính.số phiên bản phụ.số sửa đổi&quot;:</p><table tabindex="0"><thead><tr><th>Cấp Phiên bản</th><th>Quy tắc Đánh số</th><th>Điều kiện Kích hoạt</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Số phiên bản chính</td><td>Tăng từ 1</td><td>Điều chỉnh cấu trúc quan trọng trong hệ thống tài liệu, như phân chia lại mô-đun, thay đổi cài đặt cốt lõi</td><td>v1.0 → v2.0</td></tr><tr><td>Số phiên bản phụ</td><td>Tăng từ 0</td><td>Sửa đổi thực chất nội dung cốt lõi của một tài liệu, hoặc bổ sung nội dung cài đặt quan trọng</td><td>v1.0 → v1.1</td></tr><tr><td>Số sửa đổi</td><td>Tăng từ 0</td><td>Sửa đổi văn bản, điều chỉnh định dạng, thống nhất thuật ngữ và các thay đổi không thực chất khác</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>Phiên bản tổng thể của hệ thống tài liệu hiện tại là v1.0, tức là phiên bản phát hành hoàn chỉnh đầu tiên. Mỗi tài liệu ghi lại số phiên bản của chính nó trong khối thông tin tài liệu, và số phiên bản tổng thể của hệ thống tài liệu được ghi lại thống nhất trong tài liệu này.</p><h2 id="_3-xem-lai-chuan-muc-đinh-dang-tai-lieu" tabindex="-1">3. Xem lại Chuẩn mực Định dạng Tài liệu <a class="header-anchor" href="#_3-xem-lai-chuan-muc-đinh-dang-tai-lieu" aria-label="Permalink to &quot;3. Xem lại Chuẩn mực Định dạng Tài liệu&quot;">​</a></h2><p>Tất cả các tài liệu phải tuân theo các chuẩn mực định dạng thống nhất sau (chuẩn mực chi tiết xem SPEC.md):</p><h3 id="_3-1-đat-ten-tep" tabindex="-1">3.1 Đặt tên Tệp <a class="header-anchor" href="#_3-1-đat-ten-tep" aria-label="Permalink to &quot;3.1 Đặt tên Tệp&quot;">​</a></h3><p>Định dạng tên tệp là <code>XX-tiêu đề tài liệu.md</code>, trong đó XX là số hai chữ số từ 00 đến 99, tiêu đề bằng tiếng Trung, không có khoảng trắng.</p><h3 id="_3-2-cau-truc-tai-lieu" tabindex="-1">3.2 Cấu trúc Tài liệu <a class="header-anchor" href="#_3-2-cau-truc-tai-lieu" aria-label="Permalink to &quot;3.2 Cấu trúc Tài liệu&quot;">​</a></h3><p>Mỗi tài liệu phải chứa các yếu tố cấu trúc sau:</p><ol><li><strong>Tiêu đề cấp một</strong>: Tiêu đề tài liệu (nhất quán với tên tệp)</li><li><strong>Khối thông tin tài liệu</strong>: Bảng với số, mô-đun, từ khóa chính (3-5)</li><li><strong>Nội dung chính</strong>: Ít nhất 3 chương với tiêu đề cấp hai, sử dụng các yếu tố có cấu trúc như danh sách, bảng</li><li><strong>Kết luận</strong>: Đoạn tóm tắt ngắn gọn</li><li><strong>Tài liệu liên quan</strong>: Liệt kê 2-3 số và tên tài liệu liên quan</li></ol><h3 id="_3-3-yeu-cau-so-luong-tu" tabindex="-1">3.3 Yêu cầu Số lượng Từ <a class="header-anchor" href="#_3-3-yeu-cau-so-luong-tu" aria-label="Permalink to &quot;3.3 Yêu cầu Số lượng Từ&quot;">​</a></h3><p>Nội dung chính của mỗi tài liệu không được dưới 800 ký tự (không bao gồm tiêu đề và siêu dữ liệu).</p><h3 id="_3-4-phong-cach-viet" tabindex="-1">3.4 Phong cách Viết <a class="header-anchor" href="#_3-4-phong-cach-viet" aria-label="Permalink to &quot;3.4 Phong cách Viết&quot;">​</a></h3><ul><li>Phong cách tài liệu cài đặt nghiêm túc, có hệ thống, tương tự bách khoa toàn thư/tuyển tập cài đặt</li><li>Sử dụng thuật ngữ thống nhất như &quot;Hengyuanzhou&quot;, &quot;mỏ neo&quot;, &quot;cộng sinh&quot;</li><li>Các cài đặt mới được bổ sung phải tự nhất quán về mặt logic với các cài đặt hiện có, phù hợp với nguyên tắc &quot;dựa trên thực tế, nâng cấp quy luật&quot;</li></ul><h2 id="_4-to-chuc-bao-tri-va-trach-nhiem" tabindex="-1">4. Tổ chức Bảo trì và Trách nhiệm <a class="header-anchor" href="#_4-to-chuc-bao-tri-va-trach-nhiem" aria-label="Permalink to &quot;4. Tổ chức Bảo trì và Trách nhiệm&quot;">​</a></h2><h3 id="_4-1-uy-ban-bao-tri-cai-đat" tabindex="-1">4.1 Ủy ban Bảo trì Cài đặt <a class="header-anchor" href="#_4-1-uy-ban-bao-tri-cai-đat" aria-label="Permalink to &quot;4.1 Ủy ban Bảo trì Cài đặt&quot;">​</a></h3><p>Ủy ban Bảo trì Cài đặt là cơ quan bảo trì cao nhất của hệ thống tài liệu, bao gồm những người tạo cài đặt có kinh nghiệm, chuyên gia xác minh logic và đại diện người dùng. Trách nhiệm cốt lõi của nó bao gồm:</p><ul><li>Thẩm định cấu trúc tổng thể và kế hoạch sửa đổi quan trọng của hệ thống tài liệu</li><li>Xem xét các thay đổi cài đặt quan trọng, đảm bảo tính nhất quán với cài đặt cốt lõi</li><li>Quyết định các tranh chấp cài đặt, cung cấp giải thích có thẩm quyền</li><li>Tổ chức định kỳ tự kiểm tra tính nhất quán cài đặt toàn diện</li><li>Phát hành cập nhật phiên bản tổng thể của hệ thống tài liệu</li></ul><h3 id="_4-2-nguoi-bao-tri-mo-đun" tabindex="-1">4.2 Người bảo trì Mô-đun <a class="header-anchor" href="#_4-2-nguoi-bao-tri-mo-đun" aria-label="Permalink to &quot;4.2 Người bảo trì Mô-đun&quot;">​</a></h3><p>Mỗi mô-đun chỉ định một người bảo trì mô-đun, chịu trách nhiệm bảo trì hàng ngày 10 tài liệu của mô-đun đó. Trách nhiệm của họ bao gồm:</p><ul><li>Theo dõi tính nhất quán cài đặt của các tài liệu trong mô-đun</li><li>Xem xét đơn xin sửa đổi các tài liệu trong mô-đun</li><li>Phối hợp tham chiếu chéo giữa các tài liệu trong mô-đun</li><li>Thu thập phản hồi và đề xuất của người dùng về nội dung mô-đun</li><li>Báo cáo định kỳ tình trạng bảo trì mô-đun cho Ủy ban Bảo trì Cài đặt</li></ul><h3 id="_4-3-nguoi-tao-tai-lieu" tabindex="-1">4.3 Người tạo Tài liệu <a class="header-anchor" href="#_4-3-nguoi-tao-tai-lieu" aria-label="Permalink to &quot;4.3 Người tạo Tài liệu&quot;">​</a></h3><p>Bất kỳ người tạo nào đủ điều kiện đều có thể tham gia vào việc tạo và sửa đổi tài liệu. Trách nhiệm của người tạo bao gồm:</p><ul><li>Tạo hoặc sửa đổi tài liệu theo chuẩn mực định dạng</li><li>Đảm bảo nội dung tạo ra vượt qua kiểm tra của bảng tự kiểm tra mâu thuẫn cài đặt</li><li>Đính kèm hướng dẫn sửa đổi chi tiết khi gửi sửa đổi</li><li>Hợp tác với công việc xem xét của người bảo trì và ủy ban</li></ul><h2 id="_5-quy-trinh-sua-đoi" tabindex="-1">5. Quy trình Sửa đổi <a class="header-anchor" href="#_5-quy-trinh-sua-đoi" aria-label="Permalink to &quot;5. Quy trình Sửa đổi&quot;">​</a></h2><h3 id="_5-1-quy-trinh-sua-đoi-thuong-quy" tabindex="-1">5.1 Quy trình Sửa đổi Thường quy <a class="header-anchor" href="#_5-1-quy-trinh-sua-đoi-thuong-quy" aria-label="Permalink to &quot;5.1 Quy trình Sửa đổi Thường quy&quot;">​</a></h3><ol><li><strong>Gửi đơn xin</strong>: Người tạo gửi đơn xin sửa đổi cho người bảo trì mô-đun, bao gồm số tài liệu được sửa đổi, mô tả nội dung sửa đổi và lý do sửa đổi.</li><li><strong>Xem xét mô-đun</strong>: Người bảo trì mô-đun xem xét nội dung sửa đổi, tập trung vào kiểm tra chuẩn mực định dạng và tính nhất quán trong mô-đun. Sau khi vượt qua xem xét, gửi cho Ủy ban Bảo trì Cài đặt.</li><li><strong>Ủy ban thẩm định</strong>: Ủy ban Bảo trì Cài đặt thực hiện thẩm định cuối cùng đối với nội dung sửa đổi, tập trung vào kiểm tra tính nhất quán giữa các mô-đun và tính nhất quán của cài đặt cốt lõi.</li><li><strong>Thực hiện sửa đổi</strong>: Sau khi vượt qua thẩm định, người bảo trì mô-đun hoặc người tạo ban đầu thực hiện sửa đổi tài liệu.</li><li><strong>Cập nhật phiên bản</strong>: Sau khi sửa đổi hoàn tất, cập nhật số phiên bản tài liệu và ghi lại trong nhật ký cập nhật của tài liệu này.</li><li><strong>Đồng bộ hóa liên quan</strong>: Nếu nội dung sửa đổi ảnh hưởng đến các tài liệu khác, các tài liệu liên quan phải được sửa đổi đồng bộ.</li></ol><h3 id="_5-2-quy-trinh-sua-đoi-khan-cap" tabindex="-1">5.2 Quy trình Sửa đổi Khẩn cấp <a class="header-anchor" href="#_5-2-quy-trinh-sua-đoi-khan-cap" aria-label="Permalink to &quot;5.2 Quy trình Sửa đổi Khẩn cấp&quot;">​</a></h3><p>Đối với tình huống khẩn cấp phát hiện mâu thuẫn hoặc lỗi cài đặt nghiêm trọng, có thể khởi động quy trình sửa đổi khẩn cấp:</p><ol><li><strong>Báo cáo khẩn cấp</strong>: Người phát hiện ngay lập tức báo cáo vấn đề cho Ủy ban Bảo trì Cài đặt.</li><li><strong>Thẩm định nhanh chóng</strong>: Ủy ban hoàn thành thẩm định khẩn cấp trong vòng 24 giờ và cung cấp kế hoạch sửa đổi.</li><li><strong>Thực hiện sửa đổi</strong>: Chỉ định người cụ thể để ngay lập tức thực hiện sửa đổi.</li><li><strong>Ghi lại sau này</strong>: Sau khi sửa đổi hoàn tất, bổ sung ghi lại đơn xin sửa đổi và hồ sơ xem xét.</li></ol><h3 id="_5-3-sua-đoi-toan-dien-đinh-ky" tabindex="-1">5.3 Sửa đổi Toàn diện Định kỳ <a class="header-anchor" href="#_5-3-sua-đoi-toan-dien-đinh-ky" aria-label="Permalink to &quot;5.3 Sửa đổi Toàn diện Định kỳ&quot;">​</a></h3><p>Ủy ban Bảo trì Cài đặt tổ chức một lần sửa đổi toàn diện hệ thống tài liệu mỗi năm, bao gồm:</p><ul><li>Tự kiểm tra tính nhất quán cài đặt toàn diện</li><li>Xử lý tập trung phản hồi người dùng</li><li>Thống nhất và cập nhật hệ thống thuật ngữ</li><li>Cập nhật đồng bộ tài liệu lập chỉ mục</li><li>Kiểm tra và sửa đổi thống nhất định dạng tài liệu</li></ul><h2 id="_6-nhat-ky-cap-nhat" tabindex="-1">6. Nhật ký Cập nhật <a class="header-anchor" href="#_6-nhat-ky-cap-nhat" aria-label="Permalink to &quot;6. Nhật ký Cập nhật&quot;">​</a></h2><h3 id="v1-0-phat-hanh-hoan-chinh-đau-tien" tabindex="-1">v1.0 (Phát hành Hoàn chỉnh Đầu tiên) <a class="header-anchor" href="#v1-0-phat-hanh-hoan-chinh-đau-tien" aria-label="Permalink to &quot;v1.0 (Phát hành Hoàn chỉnh Đầu tiên)&quot;">​</a></h3><ul><li>Hoàn thành việc tạo và phát hành tất cả 100 tài liệu</li><li>Thiết lập cấu trúc hoàn chỉnh và chuẩn mực định dạng của hệ thống tài liệu</li><li>Hoàn thành phạm vi nội dung của mười mô-đun</li><li>Thiết lập hệ thống lập chỉ mục phụ lục (từ điển thuật ngữ, chỉ mục hệ thống, chỉ mục pháp lý, biên niên sử, danh mục tất cả các chủng tộc, nhân vật và tổ chức, FAQ, bảng tự kiểm tra, đề xuất mở rộng, hướng dẫn phiên bản)</li></ul><h3 id="khu-vuc-ghi-lai-cap-nhat-phien-ban-sau-nay" tabindex="-1">Khu vực Ghi lại Cập nhật Phiên bản Sau này <a class="header-anchor" href="#khu-vuc-ghi-lai-cap-nhat-phien-ban-sau-nay" aria-label="Permalink to &quot;Khu vực Ghi lại Cập nhật Phiên bản Sau này&quot;">​</a></h3><p>(Nội dung cập nhật của các phiên bản sau này sẽ được bổ sung ghi lại tại đây, bao gồm số phiên bản, ngày phát hành, tóm tắt nội dung cập nhật chính)</p><h2 id="_7-chuan-muc-tham-chieu-va-tham-chieu-cheo-tai-lieu" tabindex="-1">7. Chuẩn mực Tham chiếu và Tham chiếu Chéo Tài liệu <a class="header-anchor" href="#_7-chuan-muc-tham-chieu-va-tham-chieu-cheo-tai-lieu" aria-label="Permalink to &quot;7. Chuẩn mực Tham chiếu và Tham chiếu Chéo Tài liệu&quot;">​</a></h2><h3 id="_7-1-tham-chieu-noi-bo" tabindex="-1">7.1 Tham chiếu Nội bộ <a class="header-anchor" href="#_7-1-tham-chieu-noi-bo" aria-label="Permalink to &quot;7.1 Tham chiếu Nội bộ&quot;">​</a></h3><p>Tham chiếu chéo giữa các tài liệu sử dụng định dạng &quot;số tài liệu-tiêu đề tài liệu&quot;, ví dụ &quot;xem Tài liệu 84 &#39;Chương trình Tổng thể Giao thức Khảo cổ&#39;&quot;. Khi tham chiếu, phải đảm bảo rằng tài liệu được tham chiếu thực sự tồn tại và số cũng như tiêu đề là chính xác.</p><h3 id="_7-2-tham-chieu-thuat-ngu" tabindex="-1">7.2 Tham chiếu Thuật ngữ <a class="header-anchor" href="#_7-2-tham-chieu-thuat-ngu" aria-label="Permalink to &quot;7.2 Tham chiếu Thuật ngữ&quot;">​</a></h3><p>Khi sử dụng một thuật ngữ cốt lõi lần đầu tiên, có thể ghi chú rằng nên xem mục tương ứng trong Tài liệu 90 &quot;Từ điển Thuật ngữ&quot;. Không cần lặp lại ghi chú khi sử dụng cùng thuật ngữ sau này.</p><h3 id="_7-3-tham-chieu-ben-ngoai" tabindex="-1">7.3 Tham chiếu Bên ngoài <a class="header-anchor" href="#_7-3-tham-chieu-ben-ngoai" aria-label="Permalink to &quot;7.3 Tham chiếu Bên ngoài&quot;">​</a></h3><p>Nếu cần tham chiếu tài liệu thực tế hoặc tác phẩm hư cấu ngoài hệ thống cài đặt, phải ghi chú nguồn và giải thích rõ ràng rằng tham chiếu này là tài liệu tham khảo theo nguyên tắc &quot;dựa trên thực tế&quot;, không đại diện cho việc hệ thống cài đặt áp dụng hoàn toàn nội dung của nó.</p><h2 id="_8-co-che-đam-bao-chat-luong" tabindex="-1">8. Cơ chế Đảm bảo Chất lượng <a class="header-anchor" href="#_8-co-che-đam-bao-chat-luong" aria-label="Permalink to &quot;8. Cơ chế Đảm bảo Chất lượng&quot;">​</a></h2><h3 id="_8-1-tu-kiem-tra-mau-thuan-cai-đat" tabindex="-1">8.1 Tự kiểm tra Mâu thuẫn Cài đặt <a class="header-anchor" href="#_8-1-tu-kiem-tra-mau-thuan-cai-đat" aria-label="Permalink to &quot;8.1 Tự kiểm tra Mâu thuẫn Cài đặt&quot;">​</a></h3><p>Tất cả các tài liệu mới được tạo và sửa đổi phải vượt qua tất cả các mục kiểm tra của Tài liệu 97 &quot;Bảng Tự kiểm tra Mâu thuẫn Cài đặt&quot;, bao gồm hơn 40 kiểm tra trong ba hạng mục: tính nhất quán cài đặt cốt lõi, tính nhất quán logic giữa các mô-đun và chuẩn mực định dạng tài liệu.</p><h3 id="_8-2-xem-xet-cheo" tabindex="-1">8.2 Xem xét Chéo <a class="header-anchor" href="#_8-2-xem-xet-cheo" aria-label="Permalink to &quot;8.2 Xem xét Chéo&quot;">​</a></h3><p>Mỗi tài liệu phải vượt qua xem xét chéo của ít nhất một người tạo khác trước khi phát hành chính thức, tập trung vào kiểm tra tính nhất quán logic giữa các mô-đun và tính thống nhất của thuật ngữ.</p><h3 id="_8-3-co-che-phan-hoi-nguoi-dung" tabindex="-1">8.3 Cơ chế Phản hồi Người dùng <a class="header-anchor" href="#_8-3-co-che-phan-hoi-nguoi-dung" aria-label="Permalink to &quot;8.3 Cơ chế Phản hồi Người dùng&quot;">​</a></h3><p>Hệ thống tài liệu thiết lập kênh phản hồi người dùng, thông qua đó người dùng có thể gửi phản hồi theo các cách sau:</p><ul><li>Báo cáo mâu thuẫn cài đặt và lỗi logic</li><li>Đưa ra vấn đề không thống nhất thuật ngữ</li><li>Đề xuất bổ sung hoặc sửa đổi nội dung cụ thể</li><li>Chỉ ra lỗi định dạng và văn bản</li></ul><p>Tất cả các phản hồi được người bảo trì mô-đun phân loại xử lý, phản hồi quan trọng được gửi cho Ủy ban Bảo trì Cài đặt để xem xét.</p><h3 id="_8-4-bao-cao-tinh-nhat-quan-hang-quy" tabindex="-1">8.4 Báo cáo Tính nhất quán Hàng quý <a class="header-anchor" href="#_8-4-bao-cao-tinh-nhat-quan-hang-quy" aria-label="Permalink to &quot;8.4 Báo cáo Tính nhất quán Hàng quý&quot;">​</a></h3><p>Ủy ban Bảo trì Cài đặt phát hành một &quot;Báo cáo Tính nhất quán Cài đặt&quot; mỗi quý, nội dung bao gồm:</p><ul><li>Các mâu thuẫn cài đặt được phát hiện trong quý này và tình trạng xử lý</li><li>Thống kê sửa đổi tài liệu trong quý này</li><li>Tiến độ thống nhất thuật ngữ</li><li>Tình trạng xử lý phản hồi người dùng</li><li>Kế hoạch bảo trì cho quý tiếp theo</li></ul><h2 id="_9-luu-tru-va-phan-phoi-tai-lieu" tabindex="-1">9. Lưu trữ và Phân phối Tài liệu <a class="header-anchor" href="#_9-luu-tru-va-phan-phoi-tai-lieu" aria-label="Permalink to &quot;9. Lưu trữ và Phân phối Tài liệu&quot;">​</a></h2><h3 id="_9-1-đinh-dang-luu-tru" tabindex="-1">9.1 Định dạng Lưu trữ <a class="header-anchor" href="#_9-1-đinh-dang-luu-tru" aria-label="Permalink to &quot;9.1 Định dạng Lưu trữ&quot;">​</a></h3><p>Tất cả các tài liệu được lưu trữ ở định dạng Markdown (.md), đảm bảo khả năng đọc đa nền tảng và sự tiện lợi trong quản lý phiên bản. Tài liệu sử dụng mã hóa UTF-8, hỗ trợ tiếng Trung và ký tự đặc biệt.</p><h3 id="_9-2-cau-truc-thu-muc" tabindex="-1">9.2 Cấu trúc Thư mục <a class="header-anchor" href="#_9-2-cau-truc-thu-muc" aria-label="Permalink to &quot;9.2 Cấu trúc Thư mục&quot;">​</a></h3><p>Tài liệu được lưu trữ thống nhất trong thư mục <code>anchor-docs/</code>, tên tệp ở định dạng <code>XX-tiêu đề tài liệu.md</code>. SPEC.md, với tư cách là tệp chuẩn mực, cũng được lưu trữ trong cùng thư mục.</p><h3 id="_9-3-quan-ly-phien-ban" tabindex="-1">9.3 Quản lý Phiên bản <a class="header-anchor" href="#_9-3-quan-ly-phien-ban" aria-label="Permalink to &quot;9.3 Quản lý Phiên bản&quot;">​</a></h3><p>Khuyến nghị sử dụng hệ thống kiểm soát phiên bản như Git để quản lý phiên bản tài liệu, đính kèm thông điệp commit chi tiết mỗi khi gửi sửa đổi, ghi lại nội dung và lý do sửa đổi.</p><h3 id="_9-4-phuong-thuc-phan-phoi" tabindex="-1">9.4 Phương thức Phân phối <a class="header-anchor" href="#_9-4-phuong-thuc-phan-phoi" aria-label="Permalink to &quot;9.4 Phương thức Phân phối&quot;">​</a></h3><p>Hệ thống tài liệu có thể được phân phối theo các cách sau:</p><ul><li>Đóng gói thành tệp nén ZIP để tải xuống</li><li>Triển khai thành trang web tĩnh để duyệt trực tuyến</li><li>Chuyển đổi sang định dạng PDF hoặc EPUB để đọc</li><li>Nhập vào hệ thống quản lý kiến thức để quản lý có cấu trúc</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Hướng dẫn Phiên bản và Bảo trì Tài liệu là &quot;hiến pháp quản lý&quot; của hệ thống cài đặt Văn minh Cộng sinh Mỏ neo. Nó thiết lập quy tắc phiên bản, tổ chức bảo trì, quy trình sửa đổi, cơ chế đảm bảo chất lượng và phương thức lưu trữ cũng như phân phối của hệ thống tài liệu, đảm bảo rằng hệ thống cài đặt khổng lồ bao gồm 100 tài liệu này có thể luôn duy trì trật tự và tính nhất quán trong quá trình phát triển liên tục. Một hệ thống cài đặt tốt không chỉ cần nội dung xuất sắc, mà còn cần cơ chế bảo trì hoàn hảo để đảm bảo sự phát triển lành mạnh lâu dài của nó. Tài liệu này chính là người mang cốt lõi của cơ chế đó.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>97-Bảng Tự kiểm tra Mâu thuẫn Cài đặt</li><li>90-Từ điển Thuật ngữ</li><li>00-Tổng quan Vũ trụ Hengyuanzhou</li></ul>',77)])])}const p=t(u,[["render",c]]);export{d as __pageData,p as default};
